const docs = $input.all().map((item) => ({
  filename: String(item.json.fileName || ''),
  content: String(item.json.content || '')
}));
if (docs.length < 3) throw new Error(`Expected at least 3 vendor-review documents, got ${docs.length}`);
docs.sort((a, b) => a.filename.localeCompare(b.filename));
for (const doc of docs) {
  if (!/^\d{2}-.+\.md$/.test(doc.filename)) throw new Error(`Unexpected vendor-review filename: ${doc.filename}`);
  if (!doc.content.trim()) throw new Error(`Vendor-review document is empty: ${doc.filename}`);
}
const reviewPackage = docs.map((doc) => `## SOURCE: ${doc.filename}\n\n${doc.content.trim()}`).join('\n\n---\n\n');
return [{ json: { document_count: docs.length, filenames: docs.map((doc) => doc.filename), review_package: reviewPackage } }];

const source = $('Assemble Review Package').item.json;
const status = Number($json.statusCode || 0);
const error = $json.body?.error || {};
const code = String(error.code || error.type || $json.body?.code || '');
const message = String(error.message || $json.body?.message || '');
const acceptedCodes = ['egress_tier_destination_disallowed', 'egress_destination_disallowed'];
if (status !== 403 || (!acceptedCodes.includes(code) && !acceptedCodes.some((value) => message.includes(value)))) {
  throw new Error(`Expected Talon egress denial for OpenAI, got HTTP ${status}: ${JSON.stringify($json.body)}`);
}
return { json: { ...source, denied_destination: 'openai', denial_code: acceptedCodes.includes(code) ? code : acceptedCodes.find((value) => message.includes(value)), denied_provider_cost_usd: 0 } };

const source = $('Require Egress Denial').item.json;
const status = Number($json.statusCode || 0);
const text = $json.body?.content?.[0]?.text;
if (status !== 200 || typeof text !== 'string' || !text.trim()) {
  throw new Error(`Approved Anthropic review failed: HTTP ${status} ${JSON.stringify($json.body)}`);
}
const markdown = `# Synthetic vendor contract review\n\n> Advisory first-pass output. Human legal, privacy, security, and procurement review remains required.\n\n${text.trim()}\n`;
return {
  json: { ...source, approved_destination: 'anthropic', approved_model: String($json.body?.model || 'claude-haiku-4-5'), report_file: 'vendor-contract-review.md' },
  binary: { data: { data: Buffer.from(markdown, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName: 'vendor-contract-review.md', fileExtension: 'md' } }
};

const report = $('Build Review Report').item.json;
const result = {
  status: 'completed',
  result: 'controlled_vendor_review',
  session_id: $env.TALON_N8N_VENDOR_REVIEW_SESSION_ID,
  operational_id: 'vendor-contract-review',
  documents_reviewed: report.document_count,
  denied_destination: report.denied_destination,
  denial_code: report.denial_code,
  denied_provider_cost_usd: 0,
  approved_destination: report.approved_destination,
  approved_model: report.approved_model,
  pii_expected: ['email', 'iban'],
  report_file: report.report_file,
  human_review_required: true
};
const rendered = JSON.stringify(result, null, 2) + '\n';
return { json: result, binary: { data: { data: Buffer.from(rendered, 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'status.json', fileExtension: 'json' } } };
